def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    opp = [h[1] for h in history]
    me = [h[0] for h in history]

    recent_window = min(12, n)
    recent = opp[n - recent_window:]
    recent_c = sum(1 for a in recent if a == 'C')
    recent_ratio = recent_c / recent_window

    if n == 1:
        return 'C' if opp[0] == 'C' else 'D'

    last_opp = opp[-1]
    last_me = me[-1]

    # Detect long uniform runs
    if n >= 8:
        last8 = opp[-8:]
        if all(a == 'D' for a in last8):
            # Mostly give up but keep a tiny olive branch to escape DD lock.
            if rng.random() < 0.05:
                return 'C'
            return 'D'
        if all(a == 'C' for a in last8):
            return 'C'

    # Opponent seems mostly cooperative: preserve mutual cooperation,
    # but retaliate briefly against occasional defections.
    if recent_ratio >= 0.75:
        if last_opp == 'C':
            return 'C'
        # Opponent just defected while we were cooperating: short punishment.
        if last_me == 'C':
            return 'D'
        # We already punished; return to cooperation to restore mutual CC.
        return 'C'

    # Moderately cooperative opponent: tit-for-tat with forgiveness.
    if recent_ratio >= 0.45:
        if last_opp == 'C':
            return 'C'
        if last_me == 'D':
            # Try to break retaliation cycles.
            return 'C'
        # Just got defected on: retaliate once with high probability.
        return 'D' if rng.random() < 0.85 else 'C'

    # Mostly defecting opponent: defend, with occasional probes.
    if recent_ratio < 0.2:
        if last_opp == 'C' and last_me == 'D':
            # We already retaliated and they cooperated: reciprocate.
            return 'C'
        if n % 10 == 0 and rng.random() < 0.1:
            return 'C'
        return 'D'

    # Mixed opponent: mirror last move, with forgiveness after our own defection.
    if last_opp == 'D':
        if last_me == 'D':
            return 'C' if rng.random() < 0.3 else 'D'
        return 'D' if rng.random() < 0.75 else 'C'
    else:
        if last_me == 'D':
            return 'C'
        return 'C' if rng.random() < 0.9 else 'D'
